using System;using System.IO;using System.Text;using System.Security.Cryptography;using System.Xml.Serialization;
// Durable handoff between the item wallet and the existing skill file. Both
// stages are idempotent, so a crash never consumes a second bottle or resets
// skills learned after a completed reset.
public class Offline70SkillResetOutboxFG83 {public string Receipt;public string SourceFingerprint;public ushort ReturnedSp;public bool Delivered;public Offline70SkillSlotState Target;}
partial class Offline70SkillSlots {
 internal static string FingerprintFG83(Offline70SkillSlotState state){Validate(state);using(MemoryStream m=new MemoryStream()){Serializer.Serialize(m,state);using(SHA256 h=SHA256.Create()){StringBuilder b=new StringBuilder();foreach(byte n in h.ComputeHash(m.ToArray()))b.Append(n.ToString("x2"));return b.ToString();}}}
 internal static Offline70SkillSlotState ResetPlanFG83(Offline70SkillSlotState before,string receipt){Validate(before);Offline70SkillSlotState target=Default();Validate(target);for(int i=0;i<target.Slots.Length&&i<before.Slots.Length;i++)target.Slots[i]=before.Slots[i];target.CommonPlacementFG81=true;target.LastResetReceiptFG83=receipt;Validate(target);return target;}
 // The reset target's id block is one job's creation row, and those rows are not all 11 long
 // (gunner/at gunner carry 10, at mage 12). This check must therefore recognise the id block
 // without reading Offline70RoleScopeFG202.CurrentJob, because economy archives are validated for
 // every roster role while the scope may still be bound to a different character.
 internal static bool InitialIdsFG83(byte[] ids){if(ids==null||ids.Length==0||ids.Length>80)return false;for(byte job=0;job<Offline70RoleCreateJobsFG202.CreatableJobsFG202;job++){byte[] row=StartingIdsFG202(job);if(row.Length!=ids.Length)continue;int i=0;for(;i<row.Length&&row[i]==ids[i];i++){}if(i==row.Length)return true;}return false;}
 // Caller holds the skill-file lock across the economy debit and this commit.
 internal static void CommitResetFG83(string full,Offline70SkillSlotState target){Validate(target);string temp=full+".pending-"+Guid.NewGuid().ToString("N"),backup=full+Offline70StoreBackupFG354.Suffix;try{using(FileStream f=new FileStream(temp,FileMode.CreateNew,FileAccess.Write,FileShare.None)){Serializer.Serialize(f,target);f.Flush();}if(FingerprintFG83(Load(temp))!=FingerprintFG83(target))throw new InvalidDataException("Skill reset pending readback");if(File.Exists(full))File.Replace(temp,full,backup);else File.Move(temp,full);if(FingerprintFG83(Load(full))!=FingerprintFG83(target))throw new InvalidDataException("Skill reset committed readback");}finally{if(File.Exists(temp))File.Delete(temp);}}
}
class Offline70SkillResetFG83 {
 internal static bool Receipt(string text){if(String.IsNullOrEmpty(text)||text.Length>128)return false;foreach(char c in text)if(c<33||c>126)return false;return true;}
 internal static void Validate(Offline70SkillResetOutboxFG83 o){if(o==null)return;if(!Receipt(o.Receipt)||o.SourceFingerprint==null||o.SourceFingerprint.Length!=64||o.ReturnedSp==0||o.ReturnedSp>10000||o.Target==null||o.Target.LastResetReceiptFG83!=o.Receipt||o.Target.SpentSp!=0||!Offline70SkillSlots.InitialIdsFG83(o.Target.Ids))throw new InvalidDataException("Skill reset outbox bounds");foreach(char c in o.SourceFingerprint)if(c<'0'||c>'9'&&c<'a'||c>'f')throw new InvalidDataException("Skill reset fingerprint");Offline70SkillSlots.Validate(o.Target);}
 static Offline70EconomyState RecoverHeld(string economy,string skills,Action<string> boundary){Offline70EconomyState s=Offline70Economy.Load(economy);Offline70SkillResetOutboxFG83 o=s.SkillResetFG83;if(o==null||o.Delivered)return s;Validate(o);Offline70SkillSlotState current=Offline70SkillSlots.Load(skills);if(current.LastResetReceiptFG83!=o.Receipt){if(Offline70SkillSlots.FingerprintFG83(current)!=o.SourceFingerprint)throw new InvalidDataException("Pending skill reset conflicts with changed skill file");Offline70SkillSlots.CommitResetFG83(skills,o.Target);}if(boundary!=null)boundary("skills-committed");bool duplicate;s=Offline70Economy.Apply(economy,o.Receipt+"-done","skill-reset-delivered",o.Receipt,delegate(Offline70EconomyState after){if(after.SkillResetFG83==null||after.SkillResetFG83.Receipt!=o.Receipt)throw new InvalidDataException("Skill reset delivery changed");after.SkillResetFG83.Delivered=true;},out duplicate);if(boundary!=null)boundary("delivered");return s;}
 internal static Offline70EconomyState Recover(string economy,string skills){string full=Path.GetFullPath(skills);Directory.CreateDirectory(Path.GetDirectoryName(full));using(FileStream held=new FileStream(full+".lock",FileMode.OpenOrCreate,FileAccess.ReadWrite,FileShare.None))return RecoverHeld(economy,full,null);}
 internal static Offline70EconomyState Use(string economy,string skills,string receipt,ushort slot,out bool duplicate){return Use(economy,skills,receipt,slot,null,out duplicate);}
 internal static Offline70EconomyState Use(string economy,string skills,string receipt,ushort slot,Action<string> boundary,out bool duplicate){if(!Receipt(receipt)||receipt.Length>120)throw new InvalidDataException("Skill reset receipt");string full=Path.GetFullPath(skills);Directory.CreateDirectory(Path.GetDirectoryName(full));using(FileStream held=new FileStream(full+".lock",FileMode.OpenOrCreate,FileAccess.ReadWrite,FileShare.None)){RecoverHeld(economy,full,null);Offline70SkillSlotState before=Offline70SkillSlots.Load(full);Offline70EconomyState s=Offline70Economy.Apply(economy,receipt,"skill-reset",slot+":3:bank0",delegate(Offline70EconomyState after){Offline70EconomyEntry item=Offline70Economy.Find(after,0,slot);if(item==null||item.ItemId!=3||Offline70Economy.Definition(item.ItemId).Kind!=1||before.SpentSp==0)throw new InvalidDataException("Lethe bottle ownership or refundable SP");Offline70SkillSlots.Remaining(before,after.Level,after.BonusSp);after.SkillResetFG83=new Offline70SkillResetOutboxFG83{Receipt=receipt,SourceFingerprint=Offline70SkillSlots.FingerprintFG83(before),ReturnedSp=before.SpentSp,Target=Offline70SkillSlots.ResetPlanFG83(before,receipt)};uint traitRefundFG214=0;for(int i=0;i<before.Ids.Length;i++){if(before.Levels[i]==0)continue;Offline70SkillRuleFG r=Offline70SkillSlots.Rule(before.Ids[i]);if(r!=null&&r.Trait&&r.Cost==0&&r.TraitCost>0)traitRefundFG214+=(uint)r.TraitCost*before.Levels[i];}if(traitRefundFG214>0){if(traitRefundFG214>10000-after.BonusTp)traitRefundFG214=(uint)(10000-after.BonusTp);after.BonusTp=checked((ushort)(after.BonusTp+traitRefundFG214));}if(item.Quantity==1)after.Inventory.Remove(item);else item.Quantity--;},out duplicate);if(boundary!=null)boundary("item-committed");return RecoverHeld(economy,full,boundary);}}
 internal static byte[] Reply(ushort slot,bool success,byte[] keys){using(MemoryStream m=new MemoryStream())using(BinaryWriter w=new BinaryWriter(m)){w.Write((byte)(success?1:0));if(success){w.Write(slot);w.Write((byte)10);w.Write((uint)0);w.Write((ushort)0);w.Write((ushort)0);}else w.Write((byte)0x13);return Offline70RoleProtocol.BatchPacketFG(1,32,m.ToArray(),keys,true);}}
}
